"use client";

import { useId } from "react";
import {
  FormFeedback,
  SeafoamButton,
  SeafoamOutlineButton,
} from "@salesmora/ui";
import { reportTemplateCalloutData as copy } from "./report-template-callout.data";

export type ReportTemplateCalloutProps = {
  configurationLabel: string;
  canRead: boolean;
  canSave: boolean;
  activeTemplate?: { id: string; name: string; canUpdate: boolean };
  pending?: boolean;
  error?: string;
  onSave: () => void;
  onUpdate: (templateId: string) => void;
  onViewTemplates: () => void;
};

/** Requests reviewed dialogs; the host binds the displayed configuration and owns persistence/access checks. */
export function ReportTemplateCallout({
  configurationLabel,
  canRead,
  canSave,
  activeTemplate,
  pending = false,
  error,
  onSave,
  onUpdate,
  onViewTemplates,
}: ReportTemplateCalloutProps) {
  const id = useId();
  if (!canRead) return <FormFeedback kind="error" message={copy.denied} />;
  return (
    <section
      aria-labelledby={`${id}-title`}
      aria-busy={pending}
      className="grid w-full min-w-0 gap-4 rounded-2xl border border-line bg-paper p-4 text-ink sm:p-6"
    >
      <header className="grid gap-2">
        <p className="m-0 text-xs font-semibold text-muted">{copy.eyebrow}</p>
        <h2 id={`${id}-title`} className="m-0 text-xl font-semibold">
          {copy.title}
        </h2>
        <p className="m-0 text-sm leading-6 text-muted">{copy.description}</p>
      </header>
      <div className="grid gap-1 text-sm text-muted">
        <p className="m-0 wrap-anywhere">{configurationLabel}</p>
        <p className="m-0 wrap-anywhere">
          {activeTemplate ? copy.basedOn(activeTemplate.name) : copy.personal}
        </p>
      </div>
      {!canSave && !activeTemplate?.canUpdate && (
        <p className="m-0 text-sm text-muted">{copy.readOnly}</p>
      )}
      {error && <FormFeedback kind="error" message={error} />}
      {pending && (
        <p role="status" className="m-0 text-sm text-muted">
          {copy.pending}
        </p>
      )}
      <div className="flex min-w-0 flex-wrap items-center gap-3">
        <SeafoamButton
          size={16}
          label={copy.save}
          disabled={pending || !canSave}
          onClick={() => {
            if (canSave && !pending) onSave();
          }}
        />
        {activeTemplate && (
          <SeafoamButton
            size={16}
            label={copy.update}
            disabled={pending || !activeTemplate.canUpdate}
            onClick={() => {
              if (activeTemplate.canUpdate && !pending)
                onUpdate(activeTemplate.id);
            }}
          />
        )}
        <SeafoamOutlineButton
          size={16}
          label={copy.view}
          disabled={pending}
          onClick={() => {
            if (!pending) onViewTemplates();
          }}
        />
      </div>
    </section>
  );
}
